from collections import defaultdict
# 가상 로그인 기록: (분, 사용자, 결과, 접속 국가)
logs = [(0,"kim","fail","KR"),(1,"kim","fail","KR"),(1,"kim","fail","KR"),(2,"kim","fail","KR"),
        (2,"kim","fail","KR"),(3,"kim","ok","KR"),(5,"lee","ok","KR"),(6,"lee","ok","US"),
        (9,"park","fail","KR"),(40,"park","fail","KR")]
WINDOW, LIMIT = 5, 5            # 5분 안에 실패 5번이면
fails = defaultdict(list)
last_country = {}
for t, user, result, cc in logs:
    if result == "fail":
        fails[user] = [x for x in fails[user] if t - x < WINDOW] + [t]
        if len(fails[user]) >= LIMIT:
            print(f"[{t}분] 무차별 대입 의심: {user} 실패 {len(fails[user])}회")
    else:
        if len(fails[user]) >= LIMIT:
            print(f"[{t}분] 실패 직후 성공: {user} -> 계정 탈취 가능성, 세션 확인")
        if user in last_country and last_country[user][1] != cc and t - last_country[user][0] < 60:
            print(f"[{t}분] 불가능한 이동: {user} {last_country[user][1]}->{cc} {t-last_country[user][0]}분")
        last_country[user] = (t, cc)
        fails[user] = []
# [2분] 무차별 대입 의심: kim 실패 5회
# [3분] 실패 직후 성공: kim -> 계정 탈취 가능성, 세션 확인
# [6분] 불가능한 이동: lee KR->US 1분
